import type { ReactNode } from "react";

import { InlineSvg } from "./inlineSVG";

// ═══════════════════════════════════════════════════════════════════════
// Shared types only — no logic, no side effects. Consumed by the sequencer,
// the numbered command API, and the component itself; see importerUIAPI.ts
// for where the behavior these types describe lives.
// ═══════════════════════════════════════════════════════════════════════

export type MangoSource = { label: string; mark: ReactNode };

export type MangoTextOption = {
  id: string;
  title: string;
  description?: string;
  type: "text";
  default: string;
  placeholder?: string;
};
export type MangoToggleOption = {
  id: string;
  title: string;
  description?: string;
  type: "toggle";
  default: boolean;
};

export type InputSource = {
  name: string,
  mark: typeof InlineSvg,
};

export type MangoInputSourceOption = {
  sources: InputSource[],
};

export type MangoOption = MangoTextOption | MangoToggleOption;

export type MangoSettings = Record<string, string | boolean>;
export type BrowseItem = { name: string; kind: "node" | "project" };
export type MangoError = { title: string; detail?: string };

export type UmlState = "closed" | "open" | "scanning" | "review" | "confirm" | "importing" | "done";

// ── The imperative surface a host feeds an in-flight import through ───────
// Everything here is a push from the host into a running sequence — begin a
// scan, report progress, finish — which is why it's a ref handle and not
// props: this is an async process telling the UI what happened, not the UI
// telling React what to render. Numbered by call order; see the matching
// numbers on each method's implementation in importerUIAPI.ts.
export type ImportToMangoHandle = {
  /** 1. Start a run: pack the carton, hold under the scanner. */
  begin(args: { source: string; fileName?: string }): void;
  /** 2. How many records the file/API actually contains. */
  found(n: number): void;
  /** 3a. Scan succeeded — advance to the settings review. Alternative to reject(). */
  scanned(n?: number): void;
  /** 3b. Scan failed — plays the whole sequence in reverse. Alternative to scanned(). */
  reject(error: MangoError | string): void;
  /** 4. One record done — call once per item while importing, in a loop. */
  item(name?: string): void;
  /** 4a. Queue names without counting them yet (seen, not written). Loops alongside item(). */
  parsing(text: string | string[]): void;
  /** 4a. Replace the queued names outright. */
  items(list: string[]): void;
  /** 4b. Update the three completion-screen tallies. Loops alongside item(). */
  counts(c: { nodes?: number; projects?: number; skipped?: number }): void;
  /** 4c. Set the ring directly, if you're not using item() to derive it. */
  progress(n: number): void;
  /** 5. Import complete — ring to 100, completion screen. */
  finish(): void;
  /** 6. Back to closed — call to let the user start over. */
  reset(): void;
  /** Not part of the sequence — replaces the browse panel's contents (opened
   *  from the Nodes/Projects tallies). Callable any time after found(). */
  setBrowseItems(items: BrowseItem[]): void;
  readonly settings: MangoSettings;
  readonly value: number;
  readonly processed: number;
  readonly total: number;
};

export type ImportToMangoProps = {
  title?: string;
  subtitle?: string;
  sources: Record<string, MangoSource>;
  options?: MangoOption[];
  /** A CSV (or other) file was chosen or dropped. */
  onFileSelected?: (file: File) => void;
  /** The dial was pressed in API-key mode. */
  onApiKeySubmit?: (key: string) => void;
  /** "Start Import" was pressed; settings reflect the live controls. */
  onConfirm?: (settings: MangoSettings) => void;
  /** The user stopped a running import (not just closing the dialog). */
  onCancel?: () => void;
  /** "Try Again" was pressed after a rejected import. */
  onRetry?: () => void;
  onOpenWorkspace?: (e: React.MouseEvent) => void;
};

